"""One private consolidated decision page; exact selected 20-NPC distribution, no invented permission."""
from pathlib import Path
import json,re,hashlib,gzip,base64,datetime
R=Path.cwd();D=R/'docs/review-exposure';S=R/'.cache/exposure20-private'
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
t=(R/'docs/review-final/RIGHTS_REVIEW.html').read_text();assess=json.loads((D/'NPC_ASSESSMENT.json').read_text());byid={a['id']:a for a in assess['rows']}
# Keep all original native lossless views for private comparison; remove 26 separate forms.
t=re.sub(r'<fieldset>.*?</fieldset>','',t,flags=re.S)
for a in assess['rows']:
 id=a['id'];pattern=r'(<article id="'+re.escape(id)+r'".*?)(?=</article>)'
 def update(m):
  card=m.group();label='EXCLUDED · NEEDS REVIEW'if a['archive']else'INCLUDED · PASS depiction screen'
  card=re.sub(r'<span class="pill".*?</span>','<span class="pill">'+label+'</span>',card,flags=re.S)
  card=card.replace('Public release: <strong>BLOCKED</strong> pending owner decision.','Terms: <strong>UNKNOWN</strong> · exposure blocked until evidence review + exact owner approval.')
  if a['archive']:card=card.replace('<h3>','<p><strong>KHÔNG PHÂN PHỐI trong bản giới hạn 20 NPC.</strong> Hình bên dưới chỉ để chủ dự án duyệt riêng tư; không được đưa lên public.</p><h3>',1)
  return card
 t=re.sub(pattern,update,t,flags=re.S)
start=t.index('<section id="assessment">');end=t.index('<h2 id="era">',start)
summary='''<section id="assessment"><h2>Phương án phát hành ưu tiên: 20 NPC đương đại</h2><p><strong>Phase 3B-A art/gameplay/Daily Life: APPROVED. Public exposure: NOT APPROVED.</strong> Bản chuẩn 26 NPC được giữ nguyên. Bản giới hạn riêng tư đã chạy Phaser với 20 NPC thật; sáu nhân vật theo thời kỳ, video cũ và snapshot chứa họ bị loại khỏi gói này, gồm cả registry, atlas và thumbnail. Đây chưa phải bản public-safe: mọi art vẫn cần bằng chứng điều khoản dùng chung.</p><p><strong>PASS:</strong> 20 NPC đương đại vượt qua kiểm tra giới hạn về nguồn gốc hư cấu/likeness; không có tác phẩm sao chép cụ thể, logo hoặc khuôn mặt thương mại nhận diện được nào đã được xác lập. Không yêu cầu redesign họ. 309 tham chiếu nguồn và 26 atlas khớp hash; đây là PASS toàn vẹn, không phải giấy phép.</p><p><strong>NEEDS REVIEW:</strong> sáu nhân vật theo thời kỳ có liên tưởng phục trang/khuôn mặt được ghi riêng. Không xác lập nguồn cụ thể bị sao chép; phục trang văn hóa thông thường và dữ kiện lịch sử không bị tự động coi là vi phạm. Tên hư cấu không xóa nguồn cảm hứng hoặc cấp quyền. Hiện không có replacement được tạo/adopt; phương án nhỏ có điều kiện vẫn ở từng thẻ.</p><p><strong>BLOCKED:</strong> tài khoản/điều khoản có hiệu lực khi tạo art còn UNKNOWN. Chỉ bỏ sáu NPC không giải quyết phần này của 20 NPC, world, 12 playable characters và 28 cosmetics. Không dùng placeholder hay tắt gate để giả thành game đủ điều kiện.</p></section><section id="provider"><h2>Nguồn tạo ảnh và đúng bằng chứng còn thiếu</h2><p>Records xác định công cụ tích hợp <code>image_gen.imagegen</code> trong workspace OpenAI Codex, rồi native layer/rig finishing của dự án. Không ghi nhận API ảnh bên ngoài. Tên model và giá không được host cung cấp; không đòi chúng nếu điều khoản không yêu cầu. Tài khoản và hợp đồng thực tế không có trong records; không tự suy ra từ thương hiệu hoặc MIT.</p><ol><li><strong>Một xác nhận service/account:</strong> dịch vụ/loại workspace thực sự dùng (ChatGPT/Codex consumer, Business/Enterprise hoặc thỏa thuận khác) và bạn có quyền điều khiển/tạo/phân phối các output đó. Nếu nhiều account thực sự được dùng, nêu nhóm liên quan.</li><li><strong>Một bộ điều khoản áp dụng:</strong> văn bản hoặc phiên bản official có hiệu lực khi tạo, với ngày/version và mục input rights, output/use/public distribution. Một bộ có thể phủ toàn dự án nếu đúng. Không gửi token, mật khẩu, email/billing riêng hoặc 26 giấy phép nhân vật.</li></ol><p>Requests official Terms of Use / Services Agreement / Service Terms hiện bị proxy CONNECT403. Không có trích dẫn thành công nào được bịa. URL terms hiện tại không chứng minh hợp đồng quá khứ. Một quyết định cho phép preview không biến UNKNOWN thành VERIFIED.</p></section><section id="groups-summary"><h2>Tất cả nhóm sẽ được phân phối trong bản giới hạn</h2><table><thead><tr><th>Nhóm</th><th>Đánh giá / hành động</th></tr></thead><tbody><tr><td>20 NPC hư cấu</td><td>PASS depiction screen; cùng bằng chứng account/creation terms còn thiếu. Không redesign.</td></tr><tr><td>World / signage</td><td>512 file entries ở full manifest, gồm snapshot; kiểm tra nguồn và panorama dự án. Không xác lập sao chép cụ thể; upstream terms vẫn UNKNOWN.</td></tr><tr><td>12 playable characters</td><td>Giữ nguyên atlas; nguồn Juni/built-in tool và các rig liên quan được giữ. Điều khoản tạo ảnh dùng chung còn thiếu.</td></tr><tr><td>28 cosmetics</td><td>Asset paint/erase/preview giữ nguyên; không cấp thêm quyền từ việc kế thừa base art. Cùng gate điều khoản.</td></tr><tr><td>Code / font / audio</td><td>Runtime MIT; bổ sung notices thực của EventEmitter3 và các thành phần Phaser MIT/ISC/BSD. Không có font/audio file được ship. Bốn MP4 gốc chỉ có video; tất cả bị loại khỏi subset.</td></tr><tr><td>Portal / metadata / snapshots</td><td>Portal có sẵn, chỉ sửa nhãn và scope; không rebuild UI. Snapshot mới chỉ chứa 20; old all-26 checkpoint giữ riêng tư. Không ship prompts, master, contract/account records.</td></tr></tbody></table><p>Không có asset art nào được đánh dấu public-eligible trước khi kiểm tra điều khoản. Manifest bên dưới là đúng gói đang staging, không phải giấy phép. Pipeline bổ sung gate fail-closed; cả approval giả lập cũng không vượt UNKNOWN.</p></section><section id="runtime"><h2>Kiểm thử thật, giới hạn rõ ràng</h2><p>Phaser local PASS: 20/20 tiếp cận WASD, hội thoại, đóng thoại/khôi phục điều khiển, Daily Life clock; native scale 1× và nearest sampling. 656 URL ban đầu không lỗi, zero console errors; joystick landscape di chuyển Juni 37.30px. 390×844 và 667×375 browser emulation PASS. Snapshot/package được kiểm tra toàn bộ hash sau đó.</p><p>Live HTTPS game: NOT TESTED / NOT DEPLOYED. Physical Android/iPhone/GPU: NOT TESTED. V0.5, canonical game, world art và 26 approved atlases không đổi; Phase3B-B/C/D LOCKED.</p></section>'''
t=t[:start]+summary+t[end:]
# Put 20 contemporary cards before excluded six, while preserving native images exactly.
start=t.index('<h2 id="era">');end=t.index('<section id="assets">',start);part=t[start:end];cards=re.findall(r'<article.*?</article>',part,re.S);assert len(cards)==26
contemporary=[c for c in cards if 'class="card archive"'not in c];archive=[c for c in cards if 'class="card archive"'in c];assert len(contemporary)==20 and len(archive)==6
t=t[:start]+'<h2 id="others">20 NPC được đề xuất đưa vào preview giới hạn</h2><div class="grid">'+''.join(contemporary)+'</div><h2 id="era">6 NPC bị loại khỏi bản giới hạn — private review only</h2><div class="grid">'+''.join(archive)+'</div>'+t[end:]
start=t.index('<section id="decision">');end=t.index('</section>',start)+len('</section>')
t=t[:start]+'''<section id="decision"><h2>Một phản hồi tổng hợp · chưa phải approval công khai</h2><p>Hãy trả lại một bộ bằng chứng dùng chung, không cần 26 lượt duyệt. Form này chỉ xuất phản hồi để kiểm tra điều khoản; không cấp phép, không ký approval và không xuất bản. Khi bằng chứng đủ, chủ dự án sẽ quyết định đúng manifest dưới đây trong một lần.</p><label>Dịch vụ / account type và phạm vi các nguồn<input id="service" autocomplete="off" placeholder="Không đưa token hoặc thông tin billing"></label><label>Phiên bản/ngày terms + nguồn hoặc nội dung mục quyền liên quan<textarea id="terms" rows="5"></textarea></label><label>Xác nhận quyền sử dụng tài khoản và các nhóm asset được phủ<textarea id="authority" rows="3"></textarea></label><button id="response">Tải phản hồi chung để gửi lại</button><button id="approve" disabled>BLOCKED — cần kiểm tra điều khoản trước approval</button><p id="summary" role="status">Terms UNKNOWN · public exposure NOT APPROVED.</p></section>'''+t[end:]
# New metadata and exact subset manifest. No old full-scope receipt is embedded.
data={'manifestGzip':base64.b64encode(gzip.compress((S/'export-manifest.json').read_bytes(),mtime=0)).decode(),'manifestSHA256':sha(S/'export-manifest.json'),'assessment':assess,'provider':json.loads((D/'PROVIDER_EVIDENCE.json').read_text()),'request':json.loads((D/'PUBLIC_PREVIEW_APPROVAL.pending.json').read_text())}
t=t[:t.index('<script id="review-data"')]+ '<script id="review-data" type="application/json">'+json.dumps(data,ensure_ascii=False).replace('</','<\\/')+'</script>'+r'''<script>
async function start(){
 const data=JSON.parse(document.getElementById('review-data').textContent);
 const zipped=Uint8Array.from(atob(data.manifestGzip),c=>c.charCodeAt(0));
 const raw=await new Response(new Blob([zipped]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer();
 const manifest=JSON.parse(new TextDecoder().decode(raw));
 for(const image of document.querySelectorAll('[data-hero-id]'))image.src=document.getElementById(image.dataset.heroId).querySelector('.views img').src;
 document.getElementById('zoom').onchange=e=>document.body.classList.toggle('zoom',e.target.checked);
 function refresh(){const filter=document.getElementById('filter').value.toLowerCase();document.getElementById('manifest-list').textContent=manifest.files.filter(r=>r.filename.toLowerCase().includes(filter)).map(r=>r.filename+'\n SHA256 '+r.sha256+'\n Origin '+r.origin+'\n Public '+r.publicPreviewDecision+' · terms '+(r.termsEligibility??'UNKNOWN')).join('\n\n');}
 document.getElementById('filter').oninput=refresh;refresh();
 function download(name,blob){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
 document.getElementById('download-manifest').onclick=()=>download('contemporary20-exact-export-manifest.json',new Blob([raw],{type:'application/json'}));
 document.getElementById('download-provenance').textContent='Tải đánh giá 26 NPC + bằng chứng provider hiện có';
 document.getElementById('download-provenance').onclick=()=>download('rights-assessment.json',new Blob([JSON.stringify({assessment:data.assessment,provider:data.provider},null,2)],{type:'application/json'}));
 document.getElementById('response').onclick=()=>{const p={manifestSHA256:data.manifestSHA256,profile:'contemporary20',decision:'EVIDENCE_SUBMITTED_FOR_REVIEW_NOT_PUBLIC_APPROVAL',serviceAndScope:document.getElementById('service').value,termsVersionAndSupport:document.getElementById('terms').value,accountAuthorityAndCoverage:document.getElementById('authority').value,termsStatus:'UNVERIFIED_PENDING_INSPECTION'};download('owner-shared-evidence-response.json',new Blob([JSON.stringify(p,null,2)],{type:'application/json'}));};
 document.body.dataset.ready='true';
}
start().catch(e=>document.getElementById('summary').textContent='Manifest đọc lỗi: '+e.message+'; giữ BLOCKED.');
</script></body></html>'''
t=t.replace('Một trang duyệt hình ảnh & quyền · 26 NPC','Một trang quyết định · preview 20 NPC / giữ chuẩn 26 NPC')
t=t.replace('14 cư dân + 6 khách hư cấu + 6 nhân vật hư cấu theo cảm hứng thời kỳ.','Bản chuẩn: 14 cư dân + 6 khách hư cấu + 6 nhân vật theo thời kỳ. Gói giới hạn: chỉ 20 đương đại.')
t=t.replace('26 atlas giữ nguyên byte.','20 atlas trong gói giữ nguyên byte; 6 atlas khác chỉ được xem riêng tư bên dưới.')
t=t.replace('1367',str(len(json.loads((S/'export-manifest.json').read_text())['files']))).replace('40c129fb774adf14e2bd9f707d2c50e5fe24d89d438d654172ed02e33b73018d',data['manifestSHA256'])
t=t.replace('Source checkpoint: 0e4b5016 · portal f4576307 · compiled candidate ee0a928','Canonical portal f4576307 · restricted20 build adapter riêng, không sửa source chuẩn')
t=t.replace('Manifest dưới đây bao gồm game đã biên dịch, ảnh/atlas, video, metadata, runtime world, nhân vật người chơi và cosmetics.','Manifest dưới đây bao gồm game giới hạn đã biên dịch, ảnh/atlas, metadata, runtime world, 12 playable characters, 28 cosmetics và snapshot 20. Không có sáu NPC theo thời kỳ hay video cũ.')
# Drop the old setup panel and stale all26 generic classification paragraph.
t=re.sub(r'<section><details><summary>Cấu hình triển khai đã xác minh</summary>.*?</section>','',t,flags=re.S)
(D/'FINAL_REVIEW.html').write_text(t)
(D/'REVIEW_PAGE_PROOF.json').write_text(json.dumps({'bytes':len(t.encode()),'sha256':sha(D/'FINAL_REVIEW.html'),'exactManifestSHA256':data['manifestSHA256'],'includedNPCs':20,'excludedPrivateVisuals':6,'nativeViews':104,'ownerExposure':'NOT APPROVED','terms':'UNKNOWN','approvalButton':'DISABLED; evidence response only until actual inspection'},indent=2)+'\n');print('One review page',len(t.encode()),'bytes; exact manifest',data['manifestSHA256'])
